{
  "claims": [
    {
      "claim": "En Suisse, le locataire dispose d'un délai de 30 jours à compter de la réception de la chose louée pour contester le loyer initial auprès de l'autorité de conciliation, s'il considère ce loyer comme abusif.",
      "verdict": "supported"
    },
    {
      "claim": "Cette possibilité est prévue par l'art. 270 CO.",
      "verdict": "supported"
    },
    {
      "claim": "Un loyer est considéré comme abusif notamment si le bailleur a majoré le loyer initial de plus de 10 % par rapport au loyer précédent sans que des travaux à plus-value ne justifient cette hausse.",
      "verdict": "supported"
    },
    {
      "claim": "Le locataire doit être en mesure de fournir des éléments de comparaison (autres loyers du quartier) ou démontrer l'absence de travaux justifiant une hausse importante.",
      "verdict": "supported"
    }
  ],
